//! `Uri\Rfc3986\Uri` against a fixture recorded from PHP 8.5
//! (`tests/fixtures/rfc3986_driver.php` over the cases generated by
//! `tests/fixtures/gen_rfc3986_cases.py`): parsing and every getter, raw
//! and normalized, `toString()`/`toRawString()`, reference resolution,
//! `equals()` in both modes, and every `with*()` method.

mod common;
use common::*;
use goro_ext_uri::rfc3986::{ComparisonMode, Rfc3986Error, Uri};

fn ruri(u: &Uri) -> String {
    let o = |v: Option<std::borrow::Cow<'_, [u8]>>| q(v.as_deref());
    [
        o(u.scheme()),
        q(u.raw_scheme()),
        o(u.username()),
        q(u.raw_username()),
        o(u.password()),
        q(u.raw_password()),
        o(u.userinfo()),
        q(u.raw_userinfo()),
        o(u.host()),
        q(u.raw_host()),
        qi(u.port()),
        q(Some(&u.path())),
        q(Some(u.raw_path())),
        o(u.query()),
        q(u.raw_query()),
        o(u.fragment()),
        q(u.raw_fragment()),
        q(Some(&u.to_normalized_string())),
        q(Some(&u.to_raw_string())),
    ]
    .join("|")
}

fn exc(e: Rfc3986Error) -> String {
    format!(
        "EXC Uri\\InvalidUriException {}",
        q(Some(e.message().as_bytes()))
    )
}

fn res(r: Result<Uri, Rfc3986Error>) -> String {
    match r {
        Ok(u) => ruri(&u),
        Err(e) => exc(e),
    }
}

#[test]
fn rfc3986_php85_fixture() {
    run("rfc3986_php85.txt");
}

/// Seeded random inputs (`tests/fixtures/gen_fuzz.py`).
#[test]
fn rfc3986_php85_fuzz_fixture() {
    run("rfc3986_fuzz_php85.txt");
}

fn run(file: &'static str) {
    let mut rep = Report::new(file);
    for f in fixture(file) {
        let line = f.join("\t");
        let (got, want) = match f[0].as_str() {
            "P" => {
                let input = unhex(&f[1]);
                let got = match Uri::parse(&input) {
                    Ok(u) => ruri(&u),
                    Err(e) => format!("NULL\t{}", exc(e)),
                };
                (got, f[2..].join("\t"))
            }
            "R" => {
                let base = unhex(&f[1]);
                let rel = unhex(&f[2]);
                let got = match Uri::parse(&base) {
                    Err(_) => "BASEFAIL".to_string(),
                    Ok(b) => match b.resolve(&rel) {
                        Err(e) => exc(e),
                        Ok(r) => {
                            let p = Uri::parse_with_base(&rel, Some(&b))
                                .map_or("NULL".to_string(), |p| q(Some(&p.to_raw_string())));
                            format!("{}\t{p}", ruri(&r))
                        }
                    },
                };
                (got, f[3..].join("\t"))
            }
            "E" => {
                let got = match (Uri::parse(&unhex(&f[1])), Uri::parse(&unhex(&f[2]))) {
                    (Ok(a), Ok(b)) => {
                        let t = |v: bool| if v { "T" } else { "F" };
                        format!(
                            "{}{}{}",
                            t(a.equals(&b, ComparisonMode::ExcludeFragment)),
                            t(a.equals(&b, ComparisonMode::IncludeFragment)),
                            t(b.equals(&a, ComparisonMode::ExcludeFragment))
                        )
                    }
                    _ => "PARSEFAIL".into(),
                };
                (got, f[3..].join("\t"))
            }
            "W" => {
                let op = String::from_utf8(unhex(&f[2])).unwrap();
                let arg = unhex(&f[3]);
                let s = (arg[0] == b'S').then(|| &arg[1..]);
                let got = match Uri::parse(&unhex(&f[1])) {
                    Err(_) => "PARSEFAIL".into(),
                    Ok(u) => res(match op.as_str() {
                        "scheme" => u.with_scheme(s),
                        "userinfo" => u.with_userinfo(s),
                        "host" => u.with_host(s),
                        "port" => u.with_port(if arg[0] == b'I' {
                            Some(std::str::from_utf8(&arg[1..]).unwrap().parse().unwrap())
                        } else {
                            None
                        }),
                        "path" => u.with_path(s.unwrap()),
                        "query" => u.with_query(s),
                        "fragment" => u.with_fragment(s),
                        _ => unreachable!(),
                    }),
                };
                (got, f[4..].join("\t"))
            }
            _ => unreachable!("{line}"),
        };
        rep.check(|| line.clone(), &got, &want);
    }
    rep.finish();
}
